/// Registered seller accounts with authentication credentials and approval
/// workflow status.
///
/// Sellers are member-type actors who sell products on the platform. Each
/// seller must register with email and password, then obtain administrator
/// approval before listing products. The approval_status field tracks the
/// seller's standing: pending (awaiting approval), approved (can sell),
/// rejected (must reapply), or suspended (administrative action).
///
/// Account deletion is soft-deleted via deleted_at and only allowed when no
/// pending orders, cancellations, or refunds exist. When deleted, products
/// are hidden but order history and snapshots are preserved for
/// legal/compliance purposes.
///
/// {@link ecommerce_mall_seller_sessions} tracks login sessions.
/// {@link ecommerce_mall_seller_password_resets} handles password recovery.
/// {@link ecommerce_mall_seller_registrations} manages approval workflow
/// with rejection reasons.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for login and account identification.
  email String

  /// Bcrypt hashed password for authentication.
  password_hash String

  /// Account approval state: pending, approved, rejected, or suspended.
  /// Controls seller's ability to list products.
  approval_status String

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the most recent account update.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if account is active. Set when seller
  /// deletes account (if no pending transactions).
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions ecommerce_mall_seller_sessions[]
  passwordResets ecommerce_mall_seller_password_resets[]
  products ecommerce_mall_products[]
  orderItems ecommerce_mall_order_items[]
  shipments ecommerce_mall_shipments[]
  cancellationRequests ecommerce_mall_cancellation_requests[]
  refundRequests ecommerce_mall_refund_requests[]
  profileSnapshots ecommerce_mall_seller_profile_snapshots[]
  registrations ecommerce_mall_seller_registrations[]
  adminPromotionRequest ecommerce_mall_admin_promotion_request_sellers?

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([approval_status, created_at])
  @@index([deleted_at, created_at])
}

