  const superAdminGradeRequest = {
    page: 1,
    limit: 10,
    grade: "super_admin",
  } satisfies IEcommerceMallAdmin.IRequest;
  const superAdminGradeResult =
    await api.functional.ecommerceMall.superAdmin.admins.index(
      superAdminConnection,
      { body: superAdminGradeRequest },
    );
