      body: {
        search: null,
        categoryId: null,
        subcategoryId: null,
        minPrice: null,
        maxPrice: null,
        inStockOnly: true,
        sortBy: "priceDesc",
        page: null,
        limit: 10,
      } satisfies IEcommerceMallProduct.IRequest,
