    await generate_random_ecommerce_mall_seller_products_variants_options_create(
      sellerAConnection,
      {
        params: {
          productId: product.id,
          productVariantId: variant.id,
        },
      },
    );
  typia.assert(option);
  // 8. Seller B attempts to delete Seller A's option
  // This should fail with authorization error
  await TestValidator.error(
    "unauthorized deletion attempt by Seller B",
    async () => {
      await api.functional.ecommerceMall.seller.products.variants.options.erase(
        sellerBConnection,
        {
          productId: product.id,
          productVariantId: variant.id,
