  TestValidator.predicate(
    "pages count non-negative",
    optionValuesPage.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "current page positive",
    optionValuesPage.pagination.current >= 0,
  );
  TestValidator.predicate(
    "limit positive",
    optionValuesPage.pagination.limit >= 1,
  );
}

