  TestValidator.predicate(
    "snapshot has optionValues array",
    () =>
      Array.isArray(snapshot.optionValues) && snapshot.optionValues.length >= 0,
  );
  // Verify each expected option exists in the snapshot
  const expectedOptions = [
    { option_name: "Color", option_value: "Midnight Blue" },
    { option_name: "Size", option_value: "Extra Large" },
    { option_name: "Material", option_value: "Organic Cotton" },
    { option_name: "Style", option_value: "Slim Fit" },
  ];
  for (const expected of expectedOptions) {
    const found = snapshot.optionValues.find(
      (ov) =>
        ov.option_name === expected.option_name &&
        ov.option_value === expected.option_value,
    );
    TestValidator.predicate(
      `snapshot contains option ${expected.option_name}=${expected.option_value}`,
      () => found !== undefined,
    );
  }
}

