  const cartItemA =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerA_Connection,
      {
        body: {
          productVariantId: variantA.id,
          quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        },
      },
    );
  typia.assert(cartItemA);
  // Customer B: Create account and add different item to cart
  const customerB_Connection: api.IConnection = { host: connection.host };
  const customerB_Auth = await authorize_customer_join(customerB_Connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
