          quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        },
      },
    );
  typia.assert(cartItemB);
  // Test: Customer A can only see their own cart item
  const customerA_CartItems =
    await api.functional.ecommerceMall.customer.cart_items.index(
      customerA_Connection,
      {
        body: {
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(customerA_CartItems);
  TestValidator.equals(
    "Customer A cart count",
    customerA_CartItems.pagination.records,
    1,
  );
  TestValidator.equals(
    "Customer A can see their cart item",
    customerA_CartItems.data[0]?.id,
    cartItemA.id,
  );
  // Verify Customer A cannot see Customer B's cart item
  const customerB_ItemVisibleToA = customerA_CartItems.data.some(
    (item) => item.id === cartItemB.id,
  );
  TestValidator.predicate(
    "Customer A cannot see Customer B's cart item",
    !customerB_ItemVisibleToA,
  );
  // Test: Customer B can only see their own cart item
  const customerB_CartItems =
    await api.functional.ecommerceMall.customer.cart_items.index(
      customerB_Connection,
      {
        body: {
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(customerB_CartItems);
  TestValidator.equals(
    "Customer B cart count",
    customerB_CartItems.pagination.records,
    1,
  );
  TestValidator.equals(
    "Customer B can see their cart item",
    customerB_CartItems.data[0]?.id,
    cartItemB.id,
  );
  // Verify Customer B cannot see Customer A's cart item
  const customerA_ItemVisibleToB = customerB_CartItems.data.some(
    (item) => item.id === cartItemA.id,
  );
  TestValidator.predicate(
    "Customer B cannot see Customer A's cart item",
    !customerA_ItemVisibleToB,
  );
}

