export async function test_api_seller_shipment_delivery_not_found_for_undelivered(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Setup actor-specific connections
  const adminConnection: api.IConnection = { host: connection.host };
  const sellerConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // Step 2: Authenticate all actors
  await authorize_admin_join(adminConnection, {});
  await authorize_seller_join(sellerConnection, {});
  await authorize_customer_join(customerConnection, {});
  // Step 3: Admin creates category
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // Step 4: Seller creates product
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    { body: { categoryId: category.id } },
  );
  typia.assert(product);
  // Step 5: Seller creates product variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  // Step 6: Customer adds variant to cart (triggers order creation with 'paid' status)
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerConnection,
      { body: { productVariantId: variant.id, quantity: 1 } },
    );
  typia.assert(cartItem);
  // Step 7: Seller creates shipment (remains in non-delivered status)
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {},
  );
  typia.assert(shipment);
  // Step 8: Attempt to retrieve delivery - should fail with 404 Not Found
  await TestValidator.httpError(
    "delivery details should not exist for undelivered shipment",
    404,
    async () => {
      await api.functional.ecommerceMall.seller.shipments.delivery.at(
        sellerConnection,
        { shipmentId: shipment.id },
      );
    },
  );
}

