export async function test_api_shipment_delivery_not_yet_confirmed(
  connection: api.IConnection,
): Promise<void> {
  // Create isolated connections for each actor with connection isolation pattern
  const superAdminConnection: api.IConnection = { host: connection.host };
  const sellerConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // Step 1: SuperAdmin authenticates via join
  await authorize_super_admin_join(superAdminConnection, {});
  // Step 2: Seller authenticates and creates product with variant
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // Step 3: Customer authenticates and adds item to cart
  await authorize_customer_join(customerConnection, {});
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // Step 4: Seller creates shipment (in 'in_transit' status, no delivery yet)
  // The shipment is created with order items that are ready for shipping
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        carrierName: RandomGenerator.name(),
        trackingNumber: RandomGenerator.alphaNumeric(20),
      },
    },
  );
  typia.assert(shipment);
  // Verify shipment exists and has correct initial status
  TestValidator.equals(
    "shipment status is in_transit",
    shipment.status,
    "in_transit",
  );
  // Step 5 & 6: SuperAdmin attempts to retrieve delivery confirmation and verifies 404
  await TestValidator.httpError(
    "should return 404 when delivery confirmation does not exist",
    404,
    async () => {
      await api.functional.ecommerceMall.superAdmin.shipments.delivery.at(
        superAdminConnection,
        {
          shipmentId: shipment.id,
        },
      );
    },
  );
}

