  // 10. Test search with search keyword
  const searchRequests =
    await api.functional.ecommerceMall.admin.cancellation_requests.index(
      adminConnection,
      {
        body: {
          search: "test",
          limit: 15,
        } satisfies IEcommerceMallCancellationRequest.IRequest,
      },
