    MyGlobal.prisma.ecommerce_mall_guests.count({ where }),
  ]);
  const data: IEcommerceMallGuest.ISummary[] = await ArrayUtil.asyncMap(
    records,
    EcommerceMallGuestAtSummaryTransformer.transform,
