export async function getEcommerceMallCustomerRefundRequestsRefundRequestId(props: {
  customer: CustomerPayload;
  refundRequestId: string;
}): Promise<IEcommerceMallRefundRequest> {
  const record =
    await MyGlobal.prisma.ecommerce_mall_refund_requests.findFirstOrThrow({
      ...EcommerceMallRefundRequestTransformer.select(),
      where: {
        id: props.refundRequestId,
        deleted_at: null,
      },
    });
  // Verify customer has permission to view this refund request
  if (record.customer_id !== props.customer.id) {
