@Controller("/ecommerceMall/seller/inventory-records")
export class EcommercemallSellerInventory_recordsController {
  /**
   * Retrieve a single inventory record by its unique identifier.
   *
   * This operation returns the complete details of an inventory record, which represents a specific stock quantity change event for a product variant. Inventory records are immutable audit logs used to track all stock movements including restocking operations, order deductions, cancellations, refunds, and manual adjustments.
   *
   * Each inventory record includes the quantity change amount (positive for additions, negative for deductions), the reason for the change, the associated product variant, and the timestamp when the record was created.
   *
   * This endpoint is typically used by sellers when viewing detailed inventory history for a specific variant or when investigating specific stock movement events.
   *
   * @param connection
   * @param inventoryRecordId Unique identifier of the inventory record (UUID format)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Fetch the inventory record from the ecommerce_mall_inventory_records table by the provided inventoryRecordId parameter.
   *
   * The query should join with the ecommerce_mall_product_variants table to include basic variant information (SKU code, product association).
   *
   * Return a 404 error if the inventory record does not exist.
   *
   * Authorization: Only the seller who owns the associated product variant should be able to access this record. Verify ownership through the product variant's product -> seller relationship before returning data.
   *
   * The response DTO should include:
   * - id: UUID of the inventory record
   * - variantId: UUID of the associated product variant
   * - quantityChange: integer representing the stock adjustment (positive or negative)
   * - reason: text explaining the purpose of the inventory change
   * - createdAt: timestamp when the record was created
   *
   * Include nested variant summary with SKU code and productId for context.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":inventoryRecordId")
  public async at(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("inventoryRecordId")
    inventoryRecordId: string,
  ): Promise<IEcommerceMallInventoryRecord> {
    try {
      return await getEcommerceMallSellerInventoryRecordsInventoryRecordId({
        seller,
        inventoryRecordId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a filtered and paginated list of inventory records for stock movement history.
   *
   * This operation provides inventory audit capabilities for sellers to track all stock changes across their product variants. Inventory records are immutable and represent a complete audit trail of every stock movement including restocking, order placements, cancellations, refunds, and adjustments.
   *
   * Supports comprehensive filtering by product, variant, date range, reason types, and quantity change direction. Results include complete record details with variant information for full traceability of inventory movements.
   *
   * @param connection
   * @param body Search criteria and pagination parameters for filtering inventory records
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Query ecommerce_mall_inventory_records table joined with ecommerce_mall_product_variants and ecommerce_mall_products.
   *
