   * Permanently removes a cancellation request from the system.
   *
   * A cancellation request can only be erased by the customer who originally submitted it, and only while the request status is 'pending'. Once a seller has responded (approved or rejected), the cancellation request becomes immutable and cannot be erased.
   *
   * This operation performs a soft delete, marking the record as deleted while preserving it for audit purposes. The operation returns no response body on success.
   *
   * @param connection
   * @param cancellationRequestId Unique identifier of the cancellation request to erase (UUID)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Verify the authenticated user is the customer who owns the cancellation request. Check that the cancellation request exists and has status 'pending'. If the request has already been approved, rejected, or cancelled by the seller, reject with appropriate error. Perform soft delete by setting deleted_at timestamp. Return success with no body.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":cancellationRequestId")
  public async erase(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("cancellationRequestId")
    cancellationRequestId: string,
  ): Promise<void> {
    try {
      return await deleteEcommerceMallCustomerCancellationRequestsCancellationRequestId(
        {
          customer,
          cancellationRequestId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

